<?php require_once __DIR__.'/chart_local.php'; function jobrateplot($width=550,$height=400){$r=db_query("SELECT SUM(entries),MAX(UNIX_TIMESTAMP(DATE_FORMAT(date,'%Y-%m-%d'))) FROM job_history WHERE mode='s' AND date>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 3 WEEK) GROUP BY YEAR(date),MONTH(date),DAY(date) ORDER BY date","ro");$p=[];while($x=mysqli_fetch_row($r))$p[]=[date('m-d',(int)$x[1]),(float)$x[0]];echo '<div id="jobratechart_div">'.atlas_chart_bars($p,'Installation Job Submission Rate',$width,$height).'</div>';}
